    .mp-escanear{display:flex;align-items:center;justify-content:center;gap:.5rem;width:100%;min-height:3rem;margin-top:1rem;border:0;border-radius:.625rem;background:var(--primary,#2563eb);color:#fff;font:inherit;font-weight:700;cursor:pointer}.mp-aviso{display:none;margin-top:.75rem;padding:.7rem .8rem;border:1px solid color-mix(in srgb,var(--app-danger,#b42318) 38%,var(--app-border,#d0d5dd));border-radius:.625rem;background:var(--app-danger-bg,#fef2f2);color:var(--app-danger,#b42318);font-size:.8125rem;line-height:1.4}.mp-overlay{display:none;position:fixed;inset:0;z-index:100;flex-direction:column;align-items:center;justify-content:center;padding:1rem;background:#101828}.mp-overlay.activo{display:flex}.mp-camara{position:relative;width:min(100%,25rem)}.mp-overlay video{width:100%;aspect-ratio:1;border-radius:.75rem;object-fit:cover}.mp-marco{position:absolute;inset:12%;border:2px solid #fff;border-radius:.625rem;box-shadow:0 0 0 999px rgb(0 0 0 / .35);pointer-events:none}.mp-estado{max-width:23rem;margin-top:.875rem;color:#fff;font-size:.875rem;text-align:center}.mp-overlay button{font:inherit;cursor:pointer}.mp-cancelar{margin-top:1rem;padding:.6rem 1rem;border:1px solid rgb(255 255 255 / .45);border-radius:.5rem;background:transparent;color:#fff}.mp-result{display:none;width:min(100%,25rem);padding:1.25rem;border:1px solid var(--line,var(--app-border,#d0d5dd));border-radius:.75rem;background:var(--surface,var(--app-surface,#fff));color:var(--ink,var(--app-text,#172033));text-align:center}.mp-result.activo{display:block}.mp-result-icono{width:2.5rem;height:2.5rem;margin:0 auto .625rem;color:var(--app-success,#15803d)}.mp-result h2{margin:0;font-size:1.0625rem}.mp-result p{margin:.35rem 0 0;color:var(--muted,var(--app-muted,#475467));font-size:.875rem}.mp-result-botones{display:grid;grid-template-columns:1fr 1fr;gap:.625rem;margin-top:.85rem}.mp-result-botones button{min-height:2.75rem;border-radius:.5rem;font-weight:700}.mp-continuar{border:0;background:var(--primary,#2563eb);color:#fff}.mp-reintentar{border:1px solid var(--line,var(--app-border,#d0d5dd));background:var(--surface,var(--app-surface,#fff));color:var(--ink,var(--app-text,#344054)}.mp-result.error .mp-result-icono{color:var(--app-danger,#b42318)}
