</div>

<script>
(() => {
    const directo=@js($registroDirecto), iniciarBoton=document.getElementById('mp-btn-escanear'), cancelar=document.getElementById('mp-btn-cancelar'), reintentar=document.getElementById('mp-btn-reintentar'), continuar=document.getElementById('mp-btn-continuar'), overlay=document.getElementById('mp-overlay-camara'), video=document.getElementById('mp-video-camara'), estado=document.getElementById('mp-estado-camara'), avisoSoporte=document.getElementById('mp-aviso-sin-soporte'), avisoPermiso=document.getElementById('mp-aviso-sin-permiso'), vista=document.getElementById('mp-vista-camara'), resultado=document.getElementById('mp-result-qr'), titulo=document.getElementById('mp-result-titulo'), estacion=document.getElementById('mp-result-estacion'), form=document.getElementById('mp-form-registro');
    const rutaValidacion=@js(route('marcacion.validar-qr')), rutaPermitida=new URL(@js($rutaQr ?? '/marcar?token='),window.location.origin);
    let stream=null,escaneando=false,procesando=false,destino=null,token=null;
    const detener=()=>{if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}};
    const restaurar=()=>{resultado.classList.remove('activo','error');vista.style.display='block';estado.style.display='block';cancelar.style.display='inline-block';};
    const cerrar=()=>{escaneando=false;procesando=false;destino=null;token=null;detener();restaurar();overlay.classList.remove('activo');};
    const resultadoQr=(ok,mensaje,detalle='')=>{detener();escaneando=false;procesando=true;vista.style.display='none';estado.style.display='none';cancelar.style.display='none';resultado.classList.add('activo');resultado.classList.toggle('error',!ok);titulo.textContent=ok?'QR escaneado correctamente':'No se pudo validar el QR';estacion.textContent=ok?'':mensaje;continuar.style.display=ok?'inline-block':'none';};
    const leerDestino=valor=>{try{const leido=new URL(valor,window.location.origin);if(leido.origin!==window.location.origin||leido.pathname!==rutaPermitida.pathname)return null;const codigo=leido.searchParams.get('token');return codigo?{token:codigo,url:leido.toString()}:null;}catch(_){return null;}};
    const validar=async dato=>{if(!directo){destino=dato.url;token=dato.token;resultadoQr(true,'');return;}try{const respuesta=await fetch(rutaValidacion+'?token='+encodeURIComponent(dato.token),{headers:{Accept:'application/json'},credentials:'same-origin'}),cuerpo=await respuesta.json();if(!respuesta.ok||!cuerpo.confirmado){resultadoQr(false,cuerpo.mensaje||'El QR no se pudo validar.');return;}destino=dato.url;token=dato.token;resultadoQr(true,'');}catch(_){resultadoQr(false,'No se pudo validar el QR. Verifica tu conexión e inténtalo nuevamente.');}};
    const iniciar=async()=>{avisoSoporte.style.display='none';avisoPermiso.style.display='none';if(!('BarcodeDetector'in window)){avisoSoporte.style.display='block';return;}restaurar();procesando=false;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});}catch(_){avisoPermiso.style.display='block';return;}video.srcObject=stream;await video.play();overlay.classList.add('activo');const detector=new BarcodeDetector({formats:['qr_code']});escaneando=true;const ciclo=async()=>{if(!escaneando||procesando)return;try{const codigos=await detector.detect(video);if(codigos.length){const dato=leerDestino(codigos[0].rawValue||'');if(dato){procesando=true;estado.textContent='Validando QR…';await validar(dato);return;}estado.textContent='Este QR no se puede usar para marcar.';}}catch(_){}requestAnimationFrame(ciclo);};requestAnimationFrame(ciclo);};
    iniciarBoton?.addEventListener('click',iniciar);cancelar?.addEventListener('click',cerrar);reintentar?.addEventListener('click',iniciar);continuar?.addEventListener('click',()=>{if(directo&&form&&token){document.getElementById('mp-token-registro').value=token;form.submit();return;}if(destino)window.location.assign(destino);});window.addEventListener('pagehide',detener);
})();
</script>
